const gymNav=[['fitness','home','Mon quotidien'],['planning','clock','Cours & réservations'],['program','chart','Mon programme'],['coaching','users','Mon coaching'],['training','box','Mes entraînements'],['progress','chart','Mes progrès'],['membership','card','Mon abonnement'],['shop','bag','Boutique'],['myorders','bag','Mes commandes'],['myprofile','users','Mon profil']];
let classDay=1,classCategory='Tous',trainingCategory='Tous',livePass=null,passTimer=null,workoutTimer=null;
const workouts=[
{id:'strength',name:'Les fondations',tag:'Force',level:'Débutant',minutes:35,color:'olive',desc:'Prendre ses repères et retrouver le plaisir de s’entraîner.',exercises:[['Mise en route','5 min','Vélo ou marche à une allure confortable.'],['Squat au poids du corps','3 × 10','Choisissez une amplitude confortable et un mouvement contrôlé.'],['Tirage assis','3 × 12','Réglez la machine et gardez les épaules relâchées.'],['Poussée sur machine','3 × 10','Demandez au coach de vous aider à choisir la résistance.'],['Retour au calme','5 min','Marchez doucement puis relâchez vos épaules.']]},
{id:'cardio',name:'Trouver son souffle',tag:'Cardio',level:'Tous niveaux',minutes:25,color:'terra',desc:'Une séance courte pour faire le plein d’énergie.',exercises:[['Marche progressive','5 min','Augmentez progressivement votre allure.'],['Vélo à votre rythme','10 min','Restez sur une intensité confortable.'],['Marche sur tapis','5 min','Réduisez la vitesse selon vos sensations.'],['Retour au calme','5 min','Ralentissez progressivement.']]},
{id:'mobility',name:'Bouger librement',tag:'Mobilité',level:'Tous niveaux',minutes:15,color:'lavender',desc:'Un moment pour ralentir et retrouver de l’aisance.',exercises:[['Mobilité des épaules','3 min','Faites de petits mouvements lents et confortables.'],['Mobilité des hanches','4 min','Explorez une amplitude confortable, sans forcer.'],['Mobilité des chevilles','3 min','Travaillez lentement, avec un appui si nécessaire.'],['Respiration & relâchement','5 min','Prenez un moment au calme.']]},
{id:'fullbody',name:'Tout le corps en action',tag:'Force',level:'Intermédiaire',minutes:45,color:'sand',desc:'Un rendez-vous complet avec vos objectifs.',exercises:[['Mise en route','7 min','Préparez progressivement votre séance.'],['Presse à cuisses','3 × 12','Réglez la machine avec le coach.'],['Tirage vertical','3 × 12','Gardez un mouvement fluide et maîtrisé.'],['Développé sur machine','3 × 10','Utilisez une résistance adaptée à votre niveau.'],['Marche & retour au calme','8 min','Terminez à un rythme confortable.']]}
];
function migrate(){migrateBase();state.fitness??={};state.bookings??=[];state.coachBookings??=[];state.passes??=[];state.memberRequests??=[];state.classSlots??=[];for(const m of state.members){if(!state.fitness[m.id]){const example=m.id==='OD-001';state.fitness[m.id]={target:3,favorites:[],logs:example?[{id:uid(),name:'Les fondations',day:shift(-2),minutes:35,example:true},{id:uid(),name:'Bouger librement',day:shift(-4),minutes:15,example:true}]:[],weights:example?[{day:shift(-14),value:72.6},{day:shift(-7),value:72.3},{day:today(),value:72.1}]:[],running:null};}}if(!state.classSlots.some(s=>s.date===shift(6))){const templates=[['Yoga Flow','Mobilité','08:00',45,'Aïcha','Studio zen',16,6],['Circuit énergie','Cardio','12:30',30,'Ibrahima','Espace fonctionnel',16,14],['Renfo collectif','Force','18:00',45,'Fatou','Studio collectif',20,12],['Stretch & relax','Mobilité','19:00',30,'Aïcha','Studio zen',12,12]];for(let day=0;day<7;day++)templates.forEach((c,i)=>{if(!state.classSlots.some(s=>s.id==='class-'+shift(day)+'-'+i))state.classSlots.push({id:'class-'+shift(day)+'-'+i,date:shift(day),name:c[0],category:c[1],time:c[2],minutes:c[3],coach:c[4],room:c[5],capacity:c[6],exampleBooked:c[7]});});}}
const fitness=()=>state.fitness[currentMember().id];
const memberReady=()=>session.space==='client'&&!!currentMember();
const myBookings=()=>state.bookings.filter(b=>b.memberId===currentMember()?.id);
const slotTime=s=>new Date(s.date+'T'+s.time+':00Z').getTime();
const remaining=s=>Math.max(0,s.capacity-s.exampleBooked-state.bookings.filter(b=>b.slotId===s.id).length);
const shortDay=d=>new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'});
const onSite=id=>state.entries.find(e=>e.memberId===id&&!e.guest&&!e.out);
function gymTitle(title,desc,extra=''){return`<div class="gymtitle"><div><div class="eyebrow">Votre club. Votre rythme.</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function clientShell(){if(!currentMember()||!currentMember().plan)return publicClientShell();const m=currentMember();const funcs={fitness:fitnessPage,wellness:wellnessPage,body:bodyPage,insights:insightsPage,agenda:agendaPage,journal:journalPage,more:morePage,program:programPage,coaching:coachingPage,planning:planningPage,training:trainingPage,progress:progressPage,membership:membershipPage,myprofile:personalProfile,myorders:myOrdersPage,shop,discover:discoverPage};if(!funcs[page])page='fitness';const tabs=[['fitness','home','Accueil'],['agenda','clock','Agenda'],['pass','scan','Mon QR'],['training','box','Séances'],['more','users','Mon espace']];return demoBar()+`<div class="gymshell"><aside class="gymnav"><button class="gymlogo" onclick="go('fitness')"><span>✧</span><b>ORION<small>FITNESS CLUB</small></b></button><div class="gymclub">${icon('pin')}Sonfonia T7 <span>GN</span></div><div class="eyebrow navcaption">Mon espace</div><nav>${gymNav.map(([p,i,t])=>`<button class="${p===page?'active':''}" onclick="go('${p}')">${icon(i)}${t}${p==='shop'&&active(m)?`<small>−${state.settings.memberDiscount}%</small>`:''}</button>`).join('')}</nav><div class="gymnavbottom"><span class="avatar">${esc(initials(m.name))}</span><div><b>${esc(m.name)}</b><small>${m.plan||'Compte découverte'}</small></div><button class="textbtn" aria-label="Déconnexion" onclick="logout()">${icon('exit')}</button></div></aside><div class="gymworkspace"><header class="gymtop"><span>${gymNav.find(n=>n[0]===page)?.[2]||'Mon club'}</span><div><button class="textbtn" onclick="showClub()">${icon('pin')}Mon club</button><button class="btn primary small" onclick="openPass()">${icon('scan')}Mon pass QR</button><span class="avatar">${esc(initials(m.name))}</span></div></header><main class="gymmain">${funcs[page]()}<footer class="gymfoot">Orion District · Sonfonia T7 <span>Démo · données, programmes et planning fictifs</span></footer></main></div><nav class="gymmobile" aria-label="Navigation fitness">${tabs.map(([p,i,t])=>`<button class="${p===page?'active':''} ${p==='pass'?'mobileqr':''}" onclick="${p==='pass'?'openPass()':`go('${p}')`}">${icon(i)}<span>${t}</span></button>`).join('')}</nav></div>`}
function exerciseArt(kind){const forms=kind==='Cardio'?'<circle cx="60" cy="117" r="28"/><circle cx="174" cy="117" r="28"/><path d="m60 117 34-56 29 56H60l57-37 32 37h25l-28-73h-22m-44 17h30"/>':kind==='Mobilité'?'<path d="M34 139h174M58 130l51-48 39 47m-39-47 23-40m-23 40L70 68m62-26 39 16"/><circle cx="141" cy="25" r="12"/>':'<path d="m52 114 135-70M44 84l30 57M36 91l27 52m111-119 30 57m-18-63 27 52"/><path d="M31 75 83 151M165 13l52 77" stroke-width="14"/>';return`<svg class="exerciseart" viewBox="0 0 250 180" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="7" stroke-linecap="round" stroke-linejoin="round">${forms}</g></svg>`}
function fitnessPageBase(){const m=currentMember(),f=fitness(),weekStart=shift(-((new Date().getDay()+6)%7)),logs=f.logs.filter(l=>l.day>=weekStart&&l.day<=today()),pct=Math.min(100,Math.round(logs.length/f.target*100));const upcoming=myBookings().map(b=>state.classSlots.find(s=>s.id===b.slotId)).filter(s=>s&&slotTime(s)>Date.now()).sort((a,b)=>slotTime(a)-slotTime(b));return gymTitle(`On y va, ${esc(m.name.split(' ')[0])} ?`,'Chaque séance compte. Faites une place à votre énergie.',`<span class="gymdate">${shortDay(today())}</span>`)+`<div class="gymherogrid"><section class="energyhero"><div class="eyebrow">Votre prochain rendez-vous avec vous-même</div><h2>Un peu plus fort.<br>Un peu plus vous.</h2><p>${f.running?'Votre séance est en cours. Reprenez là où vous en étiez.':'35 minutes pour vous. Découvrez votre séance du jour.'}</p><button class="btn lime" onclick="${f.running?'showWorkout()':"workoutDetail('strength')"}">${icon('arrow')}${f.running?'Reprendre ma séance':'Découvrir ma séance'}</button>${exerciseArt('Force')}<span class="herostamp">ORION<br>MOVE / 01</span></section><button class="accesscard" onclick="openPass()"><div><span class="eyebrow">Votre accès au club</span><span class="badge ${active(m)?'green':'red'}">${active(m)?'Actif':'Inactif'}</span></div><div class="qrbutton">${icon('scan')}</div><h2>Mon pass d’entrée</h2><p>Un geste. Votre QR code.<br>Et votre séance peut commencer.</p><span class="accesscta">Afficher mon QR ${icon('arrow')}</span></button></div><div class="gymmetrics"><section class="weeklycard"><div class="progressring" style="--pct:${pct}%"><b>${logs.length}<small>/ ${f.target}</small></b></div><div><h3>Votre semaine prend forme.</h3><p>${logs.length>=f.target?'Objectif atteint. Bravo pour votre régularité !':`${Math.max(0,f.target-logs.length)} séance(s) pour atteindre votre objectif.`}</p><button class="textbtn" onclick="go('progress')">Voir mes progrès ${icon('arrow')}</button></div></section><button class="clubactivity" onclick="showClub()"><span class="activitydot"></span><div><b>${state.entries.filter(e=>!e.out).length} personnes au club</b><small>Présence enregistrée dans la démo</small></div>${icon('arrow')}</button></div><div class="gymsectionheading"><div><h2>Votre prochain rendez-vous</h2><p>Une place pour vous, un moment pour bouger.</p></div><button class="textbtn" onclick="go('planning')">Tout le planning ${icon('arrow')}</button></div>${upcoming.length?classRow(upcoming[0]):`<div class="nextclass"><div class="classdate">${icon('clock')}</div><div><b>À vous de choisir le prochain cours.</b><p>Yoga, cardio ou renforcement : trouvez votre rythme.</p></div><button class="btn" onclick="go('planning')">Réserver un cours</button></div>`}<div class="gymsectionheading"><div><h2>À votre rythme.</h2><p>Des séances à retrouver au club ou à la maison.</p></div><button class="textbtn" onclick="go('training')">Tous les entraînements ${icon('arrow')}</button></div><div class="workoutgrid">${workouts.slice(0,3).map(workoutCard).join('')}</div><div class="gymbottomgrid"><section class="memberperks"><span class="eyebrow">L’avantage d’être Orion</span><h2>${active(m)?'Votre remise vous suit.':'L’essentiel de votre séance.'}</h2><p>${active(m)?`−${state.settings.memberDiscount} % automatiquement dans votre boutique membre.`:'Découvrez les accessoires et tenues de votre prochaine séance.'}</p><button class="textbtn" onclick="go('shop')">Ouvrir ma boutique ${icon('arrow')}</button></section><section class="habitcard"><span class="eyebrow">Votre routine</span><h3>${m.goal?esc(m.goal):'Bouger régulièrement.'}</h3><p>Un objectif qui vous ressemble, à retrouver dans votre profil.</p><button class="textbtn" onclick="go('myprofile')">Personnaliser mon objectif ${icon('arrow')}</button></section></div>`}
function makePass(memberId){const m=state.members.find(m=>m.id===memberId);if(!m||!active(m))return null;state.passes=state.passes.filter(p=>p.expires>Date.now()&&p.memberId!==m.id);const p={id:uid(),memberId:m.id,expires:Date.now()+60000,used:false};state.passes.push(p);save();return p}
function qrSvg(text){const qr=qrcode(0,'M');qr.addData(text);qr.make();return qr.createSvgTag({cellSize:6,margin:24,scalable:true})}
function openPass(){if(!memberReady())return deny();if(!active(currentMember())){modal('Votre accès au club',`<div class="receipt"><div class="check">${icon('card')}</div><h2>Votre abonnement est inactif.</h2><p>Renouvelez votre formule auprès de l’accueil pour activer votre pass QR.</p><button class="btn primary" onclick="$('#modal').close();go('membership')">Voir mon abonnement</button></div>`);return}clearInterval(passTimer);livePass=makePass(currentMember().id);drawPass();passTimer=setInterval(tickPass,1000)}
function drawPass(){const m=currentMember();modal('Mon pass Orion',`<div class="qrmodal"><div class="eyebrow">Sonfonia T7 · Accès personnel</div><h2>${esc(m.name)}</h2><span class="badge green">${esc(m.plan)} · abonnement actif</span><div id="passMatrix" class="passmatrix">${qrSvg('ORION:'+livePass.id)}</div><div class="qrtime"><span class="activitydot"></span><span id="passCountdown">Renouvellement dans 60 s</span></div><p>Présentez ce QR au lecteur à l’entrée du club.</p>${onSite(m.id)?'<div class="notice">Vous êtes déjà au club dans la démo. <button class="textbtn" onclick="simulateMemberExit()">Simuler ma sortie avant un nouvel essai</button></div>':''}<button class="btn primary" onclick="simulatePass()">${icon('scan')}Simuler le scan à l’entrée</button><button class="textbtn" onclick="openPass()">Générer un nouveau QR</button><details><summary>Tester depuis l’accueil</summary><p>Copiez ce contenu dans le contrôle d’accès de cette même démo :</p><input aria-label="Contenu du QR" readonly value="ORION:${livePass.id}"></details><small>QR lisible, temporaire et à usage unique dans la démo.<br>Aucun tourniquet réel connecté. Validation locale dans ce navigateur.</small></div>`)}
function tickPass(){if(!$('#modal').open||!$('#passCountdown')||!memberReady()||livePass?.memberId!==currentMember()?.id){clearInterval(passTimer);return}if(!active(currentMember())){clearInterval(passTimer);$('#modal').close();return}const left=Math.ceil((livePass.expires-Date.now())/1000);if(left<=0){livePass=makePass(currentMember().id);drawPass()}else $('#passCountdown').textContent='Renouvellement dans '+left+' s'}
function consumePass(value){const id=String(value).trim().replace(/^ORION:/i,''),p=state.passes.find(p=>p.id===id);if(!p)return{ok:false,text:'QR non reconnu dans cette démo.'};if(p.used)return{ok:false,text:'Ce QR a déjà été utilisé. Générez un nouveau pass.'};if(p.expires<=Date.now())return{ok:false,text:'Ce QR a expiré. Affichez un nouveau pass.'};const m=state.members.find(m=>m.id===p.memberId);if(!m||!active(m))return{ok:false,text:'Abonnement inactif : accès refusé.'};if(onSite(m.id))return{ok:false,text:'Vous êtes déjà au club. Votre sortie doit être enregistrée avant une nouvelle entrée.'};p.used=true;state.entries.unshift({id:uid(),memberId:m.id,name:m.name,plan:m.plan,time:new Date().toISOString(),out:null,guest:false,source:'QR'});m.visits++;save();return{ok:true,text:'Entrée autorisée. Bonne séance, '+m.name.split(' ')[0]+' !'}}
function simulatePass(){if(!memberReady()||livePass?.memberId!==currentMember().id)return deny();const r=consumePass('ORION:'+livePass.id);clearInterval(passTimer);render();modal(r.ok?'Bienvenue au club':'Contrôle du pass',`<div class="receipt"><div class="check">${icon(r.ok?'check':'scan')}</div><h2>${r.ok?'Votre séance commence.':'Pass non accepté'}</h2><p>${esc(r.text)}</p><div class="notice">Simulation du lecteur d’entrée. Le résultat est visible dans le journal de réception.</div><button class="btn primary" onclick="$('#modal').close()">${r.ok?'C’est parti':'Revenir à mon espace'}</button>${onSite(currentMember().id)?'<button class="textbtn" style="display:block;margin:20px auto 0" onclick="simulateMemberExit()">Simuler ma sortie</button>':''}</div>`)}
function simulateMemberExit(){if(!memberReady())return deny();const e=onSite(currentMember().id);if(!e)return;const now=new Date().toISOString();state.entries.filter(x=>x.memberId===currentMember().id&&!x.out).forEach(x=>x.out=now);save();$('#modal').close();render();toast('Sortie enregistrée dans la démo. À bientôt !')}
function checkIn(){if(!can('entries'))return deny();const raw=$('#code').value.trim();if(/^ORION:/i.test(raw)){const r=consumePass(raw);accessMessage={error:!r.ok,text:r.text};render()}else manualCheckIn()}
function showClub(){modal('Mon club · Sonfonia T7',`<img class="clubphoto" src="building.png" alt="Façade Orion District"><h2>Votre rendez-vous fitness à Conakry.</h2><div class="details"><div><small>Horaires envisagés</small><b>6 h – 23 h</b></div><div><small>Présence dans la démo</small><b>${state.entries.filter(e=>!e.out).length} personnes</b></div><div><small>À votre disposition</small><b>Cardio · Musculation · Yoga</b></div><div><small>Sur place</small><b>Parking · Boutique</b></div></div><p class="subtle">Ouverture et horaires définitifs à confirmer. La fréquentation affichée correspond aux passages enregistrés dans cette démo.</p>${memberReady()&&onSite(currentMember().id)?'<button class="btn" style="margin-top:20px" onclick="simulateMemberExit()">Simuler ma sortie du club</button>':''}`)}
function classRow(s){const booked=myBookings().some(b=>b.slotId===s.id),past=slotTime(s)<=Date.now();return`<article class="classrow"><div class="classclock"><b>${s.time}</b><small>${s.minutes} min</small></div><div class="classsymbol ${s.category==='Cardio'?'terra':s.category==='Mobilité'?'lavender':'olive'}">${icon(s.category==='Cardio'?'chart':s.category==='Mobilité'?'home':'box')}</div><div class="classdetails"><span class="eyebrow">${s.category} · ${shortDay(s.date)}</span><h3>${s.name}</h3><p>${s.coach} · ${s.room}</p></div><div class="classavailability"><span class="badge ${booked?'green':remaining(s)?'gray':'red'}">${booked?'Réservé':remaining(s)?remaining(s)+' places':'Complet'}</span><button class="btn ${booked?'':'primary'} small" onclick="${booked?`cancelBooking('${s.id}')`:`reserveClass('${s.id}')`}" ${past||!booked&&!remaining(s)?'disabled':''}>${past?'Terminé':booked?'Annuler':'Réserver'}</button></div></article>`}
function planningPage(){const days=Array.from({length:7},(_,i)=>shift(i));if(classDay<0||classDay>6)classDay=1;const list=state.classSlots.filter(s=>s.date===days[classDay]&&(classCategory==='Tous'||s.category===classCategory));return gymTitle('Votre prochain rendez-vous.','Réservez un cours, retrouvez votre équipe et gardez votre place.')+`<div class="planningtoolbar"><div class="weekstrip">${days.map((d,i)=>`<button class="${i===classDay?'active':''}" onclick="classDay=${i};render()"><span>${new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'})}</span><b>${new Date(d+'T12:00:00').getDate()}</b><i>${myBookings().some(b=>state.classSlots.find(s=>s.id===b.slotId)?.date===d)?'•':''}</i></button>`).join('')}</div><div class="tabs">${['Tous','Force','Cardio','Mobilité'].map(c=>`<button class="${classCategory===c?'active':''}" onclick="classCategory='${c}';render()">${c}</button>`).join('')}</div></div><div class="bookingnote">${icon('check')} ${myBookings().filter(b=>{let s=state.classSlots.find(s=>s.id===b.slotId);return s&&slotTime(s)>Date.now()}).length} réservation(s) à venir <span>Inclus dans votre abonnement actif</span></div><section class="panel classlist">${list.map(classRow).join('')||'<div class="empty">Aucun cours pour cette sélection.</div>'}</section><div class="notice">Planning, coachs et places d’exemple. Vous pouvez réserver ou annuler sans envoyer de demande réelle au club.</div>`}
function reserveClass(id){if(!memberReady()||!active(currentMember())){toast('Un abonnement actif est nécessaire pour réserver.');return}const s=state.classSlots.find(s=>s.id===id);if(!s||slotTime(s)<=Date.now())return toast('Ce cours a déjà commencé.');if(s.date>currentMember().expiry)return toast('Renouvelez votre abonnement pour réserver à cette date.');if(myCoaching().some(b=>coachTime(b)<slotTime(s)+s.minutes*60000&&coachTime(b)+30*60000>slotTime(s)))return toast('Vous avez déjà un coaching sur ce créneau.');if(myBookings().some(b=>b.slotId===id))return toast('Votre place est déjà réservée.');if(!remaining(s))return toast('Ce cours est complet.');const conflict=myBookings().some(b=>{const o=state.classSlots.find(x=>x.id===b.slotId);return o&&slotTime(s)<slotTime(o)+o.minutes*60000&&slotTime(o)<slotTime(s)+s.minutes*60000});if(conflict)return toast('Vous avez déjà un cours sur ce créneau.');state.bookings.push({id:uid(),memberId:currentMember().id,slotId:id});save();render();toast('Votre place est réservée · '+s.name+' à '+s.time)}
function cancelBooking(id){if(!memberReady())return deny();state.bookings=state.bookings.filter(b=>!(b.memberId===currentMember().id&&b.slotId===id));save();render();toast('Réservation annulée. Votre place est libérée.')}
function workoutCard(w){const favorite=fitness().favorites.includes(w.id);return`<article class="workoutcard"><div class="workoutart ${w.color}">${exerciseArt(w.tag)}<span>${w.minutes}<small> MIN</small></span><button aria-label="${favorite?'Retirer des favoris':'Ajouter aux favoris'} ${w.name}" class="favorite ${favorite?'selected':''}" onclick="favoriteWorkout('${w.id}')">${favorite?'♥':'♡'}</button></div><div class="workoutbody"><div class="eyebrow">${w.tag} · ${w.level}</div><h3>${w.name}</h3><p>${w.desc}</p><button class="textbtn" onclick="workoutDetail('${w.id}')">Voir la séance ${icon('arrow')}</button></div></article>`}
function trainingPage(){const f=fitness(),list=workouts.filter(w=>trainingCategory==='Tous'||trainingCategory==='Favoris'&&f.favorites.includes(w.id)||w.tag===trainingCategory);return gymTitle('De l’envie à l’action.','Choisissez votre séance. Suivez les étapes. Gardez une trace de vos efforts.')+`${f.running?`<div class="runningbanner"><div>${icon('clock')}<b>Une séance vous attend</b><span>${workouts.find(w=>w.id===f.running.workoutId)?.name}</span></div><button class="btn primary" onclick="showWorkout()">Reprendre</button></div>`:''}<div class="toolbar"><div class="tabs">${['Tous','Force','Cardio','Mobilité','Favoris'].map(c=>`<button class="${c===trainingCategory?'active':''}" onclick="trainingCategory='${c}';render()">${c}</button>`).join('')}</div><span class="subtle">${list.length} séance(s) · au club ou chez vous</span></div><div class="workoutgrid">${list.map(workoutCard).join('')||'<div class="empty">Ajoutez une séance à vos favoris avec le cœur.</div>'}</div><div class="notice">Séances d’exemple, à adapter avec votre coach à votre niveau et aux machines disponibles. Les durées indiquées servent de repères.</div>`}
function favoriteWorkout(id){if(!memberReady()||!workouts.some(w=>w.id===id))return;let f=fitness();f.favorites=f.favorites.includes(id)?f.favorites.filter(x=>x!==id):[...f.favorites,id];save();render()}
function workoutDetail(id){const w=workouts.find(w=>w.id===id);if(!memberReady()||!w)return;modal(w.name,`<div class="workoutdetail ${w.color}">${exerciseArt(w.tag)}<div><span class="eyebrow">${w.tag} · ${w.level}</span><h2>${w.minutes} minutes pour vous.</h2><p>${w.desc}</p></div></div><div class="exerciselist">${w.exercises.map((e,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><p><b>${e[0]}</b><small>${e[1]}</small></p></div>`).join('')}</div><button class="btn primary wide" onclick="startWorkout('${id}')">${icon('arrow')}Commencer la séance</button><p class="subtle" style="margin-top:15px">Programme illustratif. Demandez au coach de valider les réglages et les mouvements.</p>`)}
function startWorkout(id){if(!memberReady()||!workouts.some(w=>w.id===id))return;if(fitness().running){showWorkout();toast('Reprenez votre séance en cours avant d’en commencer une autre.');return}fitness().running={workoutId:id,started:Date.now(),checked:[],pauseUntil:0};save();showWorkout()}
function showWorkout(){if(!memberReady()||!fitness().running)return;const r=fitness().running,w=workouts.find(w=>w.id===r.workoutId);clearInterval(workoutTimer);modal('Ma séance en cours',`<div class="sessionheadline"><div><span class="eyebrow">${w.tag} · ${w.minutes} min prévues</span><h2>${w.name}</h2></div><b>${r.checked.length}/${w.exercises.length}</b></div><div class="sessionprogress"><span style="width:${r.checked.length/w.exercises.length*100}%"></span></div><div class="sessionsteps">${w.exercises.map((e,i)=>`<button class="${r.checked.includes(i)?'done':''}" onclick="toggleExercise(${i})"><span>${r.checked.includes(i)?icon('check'):String(i+1).padStart(2,'0')}</span><div><b>${e[0]}</b><small>${e[1]}</small><p>${e[2]}</p></div></button>`).join('')}</div><div class="resttimer"><span>${icon('clock')}Repos <b id="restCount">${Math.max(0,Math.ceil((r.pauseUntil-Date.now())/1000))} s</b></span><button class="textbtn" onclick="startRest()">Lancer 60 secondes</button></div><button class="btn primary wide" onclick="finishWorkout()" ${r.checked.length===w.exercises.length?'':'disabled'}>Terminer et enregistrer</button><button class="textbtn" style="display:block;margin:18px auto 0" onclick="abandonWorkout()">Abandonner cette séance</button>`);workoutTimer=setInterval(()=>{if(!$('#modal').open||!memberReady()||!fitness().running||!$('#restCount')){clearInterval(workoutTimer);return}$('#restCount').textContent=Math.max(0,Math.ceil((fitness().running.pauseUntil-Date.now())/1000))+' s'},1000)}
function toggleExercise(i){if(!memberReady()||!fitness().running)return;const r=fitness().running,w=workouts.find(w=>w.id===r.workoutId);if(!Number.isInteger(i)||i<0||i>=w.exercises.length)return;r.checked=r.checked.includes(i)?r.checked.filter(x=>x!==i):[...r.checked,i];save();showWorkout()}
function startRest(){if(!memberReady()||!fitness().running)return;fitness().running.pauseUntil=Date.now()+60000;save();showWorkout()}
function finishWorkout(){if(!memberReady()||!fitness().running)return;const r=fitness().running,w=workouts.find(w=>w.id===r.workoutId);if(r.checked.length!==w.exercises.length)return;fitness().logs.unshift({id:uid(),workoutId:w.id,name:w.name,day:today(),minutes:w.minutes,example:false});fitness().running=null;clearInterval(workoutTimer);save();render();modal('Une séance de plus pour vous.',`<div class="receipt"><div class="check">${icon('check')}</div><h2>Bien joué !</h2><p>${w.name} est enregistré dans vos progrès.<br>${w.exercises.length} étapes validées · ${w.minutes} min prévues</p><button class="btn primary" onclick="$('#modal').close();go('progress')">Voir mes progrès</button></div>`)}
function abandonWorkout(){modal('Abandonner la séance ?',`<p>Cette séance ne sera pas ajoutée à vos progrès.</p><div class="actions"><button class="btn" onclick="showWorkout()">Continuer</button><button class="btn primary" onclick="confirmAbandonWorkout()">Abandonner</button></div>`)}
function confirmAbandonWorkout(){if(!memberReady())return;fitness().running=null;clearInterval(workoutTimer);save();$('#modal').close();render()}
function progressPageBase(){const f=fitness(),logs=[...f.logs].sort((a,b)=>b.day.localeCompare(a.day)),minutes=logs.reduce((s,l)=>s+l.minutes,0),weights=[...f.weights].sort((a,b)=>a.day.localeCompare(b.day));return gymTitle('Regardez le chemin parcouru.','Votre régularité mérite d’être visible.',button('Ajouter une mesure','weightForm()','','plus'))+`<div class="progressstats"><article><small>Séances enregistrées</small><b>${logs.length}</b><p>Chaque rendez-vous compte</p></article><article><small>Temps de programme cumulé</small><b>${minutes}<em> min</em></b><p>Durées prévues des séances</p></article><article><small>Dernière mesure</small><b>${weights.length?weights.at(-1).value:'—'}<em> kg</em></b><p>${weights.length?shortDay(weights.at(-1).day):'Ajoutez votre premier repère'}</p></article></div><div class="progressgrid"><section class="panel chartpanel"><div class="panelhead"><div><h2>Mon poids, mes repères</h2><p>Un suivi personnel, sans objectif imposé.</p></div><button class="textbtn" onclick="weightForm()">Ajouter ${icon('plus')}</button></div>${weightChart(weights)}<div class="weightpoints">${weights.slice(-4).map(w=>`<span>${shortDay(w.day)}<b>${w.value} kg</b></span>`).join('')}</div></section><section class="panel weeklygoal"><span class="eyebrow">Votre rythme</span><h2>Un objectif réaliste.</h2><p>Choisissez le nombre de séances que vous souhaitez enregistrer chaque semaine.</p><form onsubmit="event.preventDefault();saveTarget()"><label for="weeklyTarget">Séances par semaine</label><select id="weeklyTarget">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${f.target===n?'selected':''}>${n} séance${n>1?'s':''}</option>`).join('')}</select><button class="btn primary">Enregistrer mon rythme</button></form></section></div><div class="gymsectionheading"><div><h2>Mon carnet d’entraînement</h2><p>Les séances que vous avez terminées.</p></div></div><section class="panel loglist">${logs.map(l=>`<div>${icon('check')}<span><b>${esc(l.name)}</b><small>${shortDay(l.day)} ${l.example?'· exemple':''}</small></span><strong>${l.minutes} min prévues</strong></div>`).join('')||'<div class="empty">Terminez votre première séance pour la retrouver ici.</div>'}</section>`}
function weightChart(ws){if(ws.length<2)return'<div class="empty">Ajoutez deux mesures pour visualiser votre évolution.</div>';const a=ws.slice(-12),min=Math.min(...a.map(x=>x.value))-1,max=Math.max(...a.map(x=>x.value))+1,points=a.map((x,i)=>[30+i/(a.length-1)*500,150-(x.value-min)/(max-min)*110]);return`<svg class="weightchart" viewBox="0 0 560 180" role="img" aria-label="Poids : ${a.map(w=>w.value+' kilogrammes le '+w.day).join(', ')}"><path d="M30 45H530M30 95H530M30 150H530" stroke="#544834" stroke-dasharray="4 5"/><path d="M${points.map(p=>p.join(' ')).join(' L')} L530 160 L30 160Z" fill="#edba5922"/><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#edba59" stroke-width="3"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#edba59" stroke="#19191c" stroke-width="3"/>`).join('')}</svg>`}
function weightForm(){if(!memberReady())return deny();modal('Ajouter un repère',`<form onsubmit="event.preventDefault();saveWeight()"><div class="field"><label for="measureDate">Date de la mesure</label><input id="measureDate" type="date" max="${today()}" value="${today()}" required></div><div class="field"><label for="measureWeight">Poids (kg)</label><input id="measureWeight" type="number" min="20" max="400" step="0.1" required placeholder="Ex. 72,5"></div><p class="subtle">Une mesure par jour. Enregistrer une mesure à la même date remplace la précédente. Utilisez des données fictives dans cette démo.</p><button class="btn primary" style="margin-top:20px">Enregistrer la mesure</button></form>`)}
function saveWeight(){if(!memberReady())return deny();const day=$('#measureDate').value,value=Number($('#measureWeight').value);if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!Number.isFinite(new Date(day).getTime())||day>today()||!Number.isFinite(value)||value<20||value>400)return toast('Vérifiez la date et le poids saisis.');fitness().weights=fitness().weights.filter(w=>w.day!==day);fitness().weights.push({day,value});const latest=[...fitness().weights].sort((a,b)=>a.day.localeCompare(b.day)).at(-1);currentMember().weight=String(latest.value);save();$('#modal').close();render();toast('Votre mesure est enregistrée.')}
function saveTarget(){if(!memberReady())return;const n=Number($('#weeklyTarget').value);if(!Number.isInteger(n)||n<1||n>7)return;fitness().target=n;save();render();toast('Votre objectif hebdomadaire est mis à jour.')}
function membershipPage(){const m=currentMember(),payments=state.payments.filter(p=>p.memberId===m.id),requests=state.memberRequests.filter(r=>r.memberId===m.id);return gymTitle('Votre abonnement, en clair.','Vos accès, vos avantages et vos demandes au même endroit.')+`<div class="membershipgrid"><section class="membershipcard"><span class="eyebrow">ORION DISTRICT · MEMBER</span><div class="membershipname">${m.plan||'Découverte'}<span>✧</span></div><p>${esc(m.name)}<small>${m.id}</small></p><div><span>${active(m)?'ACTIF':'INACTIF'}<small>${m.expiry?'Valable jusqu’au '+date(m.expiry):'Sans abonnement fitness'}</small></span><b>${m.plan?money(planPrices[m.plan]):'—'}<small>/ mois</small></b></div></section><section class="panel benefitslist"><h2>Tout ce qui est inclus.</h2>${['Accès cardio, musculation et espaces sportifs','Cours collectifs selon le planning',...(m.plan==='Premium'||m.plan==='VIP'?['Massage et programme nutritionnel',m.plan==='VIP'?'2 coachings par semaine':'1 coaching par semaine']:[]),...(m.plan==='VIP'?['1 proche invité par visite']:[]),`Remise boutique de ${state.settings.memberDiscount} % pour les membres actifs connectés`].map(t=>`<div>${icon('check')}<span>${t}</span></div>`).join('')}<div class="actions"><button class="btn primary" onclick="openPass()">${icon('scan')}Mon pass QR</button>${m.plan==='VIP'?'<button class="btn" onclick="inviteMyGuest()">Inviter un proche</button>':''}</div></section></div><div class="accountactions"><button onclick="memberRequest('Changer de formule')">${icon('card')}<span><b>Changer de formule</b><small>Préparer une demande pour l’accueil</small></span>${icon('arrow')}</button><button onclick="memberRequest('Renouveler mon abonnement')">${icon('clock')}<span><b>Renouveler mon abonnement</b><small>Retrouver le club sans interruption</small></span>${icon('arrow')}</button><button onclick="go('myprofile')">${icon('users')}<span><b>Mes informations</b><small>Coordonnées et profil fitness</small></span>${icon('arrow')}</button><button onclick="go('myorders')">${icon('bag')}<span><b>Mes commandes boutique</b><small>Achats, remises et retraits</small></span>${icon('arrow')}</button></div><div class="gymsectionheading"><h2>Mes demandes</h2></div><section class="panel loglist">${requests.map(r=>`<div>${icon('card')}<span><b>${esc(r.type)}${r.plan?' · '+esc(r.plan):''}</b><small>${shortDay(r.date)} · Demande démo</small></span><span class="badge ${r.status==='Traitée'?'green':'vip'}">${r.status}</span></div>`).join('')||'<div class="empty">Aucune demande en cours.</div>'}</section><div class="gymsectionheading"><h2>Historique des règlements démo</h2></div><section class="panel loglist">${payments.map(p=>`<div>${icon('check')}<span><b>${esc(p.type)}</b><small>${date(p.time.slice(0,10))}</small></span><strong>${money(p.total)}</strong></div>`).join('')||'<div class="empty">Aucun règlement enregistré pour ce compte de démonstration.</div>'}</section>`}
function memberRequest(type){if(!memberReady())return deny();modal(type,`<form onsubmit="event.preventDefault();saveMemberRequest('${type}')"><p>Cette demande sera visible dans la gestion des clients de la démo.</p>${type==='Changer de formule'?`<div class="field" style="margin-top:20px"><label for="requestPlan">Formule souhaitée</label><select id="requestPlan">${Object.keys(planPrices).map(p=>`<option value="${p}">${p} · ${money(planPrices[p])} / mois</option>`).join('')}</select></div>`:''}<div class="notice">Aucun prélèvement ni envoi externe. Votre abonnement actuel reste inchangé jusqu’au traitement de la demande.</div><button class="btn primary">Enregistrer ma demande démo</button></form>`)}
function saveMemberRequest(type){if(!memberReady()||!['Changer de formule','Renouveler mon abonnement'].includes(type))return;const plan=type==='Changer de formule'?$('#requestPlan').value:null;if(plan&&!planPrices[plan])return;if(state.memberRequests.some(r=>r.memberId===currentMember().id&&r.type===type&&r.status==='À traiter'))return toast('Vous avez déjà une demande similaire en cours.');state.memberRequests.unshift({id:uid(),memberId:currentMember().id,type,plan,status:'À traiter',date:today()});save();$('#modal').close();render();toast('Votre demande est enregistrée dans la démo.')}
function requestsPanel(){if(!can('clients'))return'';return`<section class="panel" style="margin-bottom:22px"><div class="panelhead"><h2>Demandes des membres</h2><span class="badge">${state.memberRequests.filter(r=>r.status==='À traiter').length} à traiter</span></div><div class="tablewrap"><table><thead><tr><th>Membre</th><th>Demande</th><th>Statut</th><th></th></tr></thead><tbody>${state.memberRequests.map(r=>`<tr><td>${esc(state.members.find(m=>m.id===r.memberId)?.name||r.memberId)}</td><td>${esc(r.type)}${r.plan?' · '+r.plan:''}</td><td>${r.status}</td><td>${r.status==='À traiter'?`<button class="btn small" onclick="processMemberRequest('${r.id}')">Traiter</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Aucune demande membre.</td></tr>'}</tbody></table></div></section>`}
function processMemberRequest(id){if(!can('clients'))return deny();const r=state.memberRequests.find(r=>r.id===id),m=state.members.find(m=>m.id===r?.memberId);if(!r||!m||r.status!=='À traiter')return;modal('Traiter la demande',`<p>${esc(m.name)} · ${esc(r.type)}</p><div class="field" style="margin-top:20px"><label for="requestProcessPlan">Formule à activer pendant 30 jours</label><select id="requestProcessPlan">${Object.keys(planPrices).map(p=>`<option value="${p}" ${p===(r.plan||m.plan)?'selected':''}>${p} · ${money(planPrices[p])}</option>`).join('')}</select></div><div class="notice">Le règlement est simulé. La même formule active est prolongée de 30 jours ; une nouvelle formule commence aujourd’hui.</div><button class="btn primary" onclick="approveMemberRequest('${id}')">Confirmer le traitement démo</button>`)}
function approveMemberRequest(id){if(!can('clients'))return deny();const r=state.memberRequests.find(r=>r.id===id),m=state.members.find(m=>m.id===r?.memberId),p=$('#requestProcessPlan').value;if(!r||!m||r.status!=='À traiter'||!planPrices[p])return;const base=m.plan===p&&active(m)?m.expiry:today();m.plan=p;m.expiry=shift(30,base);state.payments.push({id:uid(),memberId:m.id,total:planPrices[p],time:new Date().toISOString(),type:r.type});r.status='Traitée';save();$('#modal').close();render();toast('Demande traitée et abonnement mis à jour.')}
$('#modal').addEventListener('close',()=>{clearInterval(passTimer);clearInterval(workoutTimer)});
const coaches=[{id:'c1',name:'Fatou Camara',initials:'FC',specialty:'Reprise & mobilité',note:'Retrouvez vos repères et construisez votre routine.'},{id:'c2',name:'Ibrahima Diallo',initials:'ID',specialty:'Force & technique',note:'Prenez le temps de découvrir les machines et les mouvements.'}];
function programPrefs(){return fitness().program||{goal:'routine',level:'beginner',duration:45};}
function programSessions(){const p=programPrefs(),force=p.level==='regular'&&p.duration>=45?'fullbody':'strength',base=p.goal==='mobility'?['mobility','cardio','mobility','strength']:p.goal==='cardio'?['cardio','mobility','cardio','strength']:[force,'cardio','mobility',force];return Array.from({length:fitness().target},(_,i)=>{let w=workouts.find(w=>w.id===base[i%base.length]);if(w.minutes>p.duration)w=workouts.find(w=>w.id===(p.duration>=25?'cardio':'mobility'));return w});}
function programPage(){const p=programPrefs(),labels={routine:'Créer ma routine',cardio:'Travailler mon endurance',mobility:'Gagner en aisance'},sessions=programSessions();return gymTitle('Un programme qui vous ressemble.','Vos préférences, votre rythme. Une semaine à construire ensemble.',`<button class="btn" onclick="programForm()">${icon('users')}Mes préférences</button>`)+`<section class="programbanner"><div><span class="eyebrow">ORION / MY ROUTINE</span><h2>${labels[p.goal]}</h2><p>${fitness().target} rendez-vous par semaine · ${p.level==='beginner'?'Débutant':'Pratiquant régulier'} · jusqu’à ${p.duration} min</p><button class="btn primary" onclick="programForm()">Personnaliser mon programme ${icon('arrow')}</button></div><div class="programnumber">${String(fitness().target).padStart(2,'0')}<small>SÉANCES / SEMAINE</small></div></section><div class="gymsectionheading"><div><h2>Ma semaine, à mon rythme</h2><p>Choisissez vos jours et espacez vos séances selon vos disponibilités.</p></div></div><div class="programgrid">${sessions.map((w,i)=>`<article class="panel programstep"><span class="eyebrow">RENDEZ-VOUS ${String(i+1).padStart(2,'0')}</span><div class="programart">${exerciseArt(w.tag)}</div><span class="badge vip">${w.tag} · ${w.minutes} min</span><h3>${w.name}</h3><p>${w.desc}</p><button class="btn wide" onclick="workoutDetail('${w.id}')">Voir ma séance ${icon('arrow')}</button></article>`).join('')}</div><div class="notice">Sélection de séances types selon vos préférences, proposée pour cette démo. Un coach pourra ajuster les exercices et les charges avec vous.</div><button class="textbtn" onclick="go('coaching')">Faire le point avec un coach ${icon('arrow')}</button>`;}
function programForm(){if(!memberReady())return;const p=programPrefs();modal('Mon programme, mes préférences',`<form onsubmit="event.preventDefault();saveProgram()"><div class="field"><label for="programGoal">Mon intention</label><select id="programGoal">${[['routine','Créer ma routine'],['cardio','Travailler mon endurance'],['mobility','Gagner en aisance']].map(([v,t])=>`<option value="${v}" ${p.goal===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="programLevel">Mon expérience</label><select id="programLevel"><option value="beginner" ${p.level==='beginner'?'selected':''}>Je débute ou je reprends</option><option value="regular" ${p.level==='regular'?'selected':''}>Je pratique régulièrement</option></select></div><div class="formrow"><div class="field"><label for="programTarget">Séances par semaine</label><select id="programTarget">${[1,2,3,4,5,6,7].map(n=>`<option ${fitness().target===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="programDuration">Temps disponible par séance</label><select id="programDuration">${[15,25,35,45].map(n=>`<option value="${n}" ${p.duration===n?'selected':''}>${n} minutes</option>`).join('')}</select></div></div><button class="btn primary wide">Créer ma semaine</button></form>`);}
function saveProgram(){if(!memberReady())return;const goal=$('#programGoal').value,level=$('#programLevel').value,duration=Number($('#programDuration').value),target=Number($('#programTarget').value);if(!['routine','cardio','mobility'].includes(goal)||!['beginner','regular'].includes(level)||![15,25,35,45].includes(duration)||!Number.isInteger(target)||target<1||target>7)return;fitness().program={goal,level,duration};fitness().target=target;save();$('#modal').close();go('program');toast('Votre semaine est prête. Vous pouvez ajuster votre rythme à tout moment.');}
function coachTime(b){return new Date(b.day+'T'+b.time+':00Z').getTime();}
function weekOf(day){const d=new Date(day+'T12:00:00');return shift(-((d.getDay()+6)%7),day);}
function coachQuota(m){return m.plan==='VIP'?2:m.plan==='Premium'?1:0;}
function myCoaching(){return state.coachBookings.filter(b=>b.memberId===currentMember().id).sort((a,b)=>coachTime(a)-coachTime(b));}
function coachingPage(){const m=currentMember(),quota=coachQuota(m),booked=myCoaching().filter(b=>coachTime(b)>Date.now()),used=myCoaching().filter(b=>weekOf(b.day)===weekOf(today())).length;return gymTitle('Votre coach, votre prochain déclic.','Un accompagnement individuel pour prendre confiance et avancer.')+`<section class="coachingcredit"><div>${icon('card')}<span><b>${quota?`${Math.max(0,quota-used)} crédit${quota-used>1?'s':''} disponible${quota-used>1?'s':''} cette semaine`:'Le coaching individuel, en complément'}<small>${quota?`${m.plan} · ${quota} séance${quota>1?'s':''} incluse${quota>1?'s':''} par semaine`:'Inclus dans les formules Premium et VIP'}</small></span></div><button class="textbtn" onclick="go('membership')">Ma formule ${icon('arrow')}</button></section><div class="gymsectionheading"><div><h2>Mes rendez-vous</h2><p>Réservations fictives, visibles par l’équipe d’accueil dans cette démo.</p></div></div>${booked.map(b=>`<div class="nextclass coachappointment"><div class="classdate">${icon('clock')}</div><div><b>${esc(coaches.find(c=>c.id===b.coachId)?.name||'Coach')} · ${shortDay(b.day)} à ${b.time}</b><p>30 minutes · studio coaching · ${esc(b.focus)}</p></div><button class="btn small" onclick="cancelCoaching('${b.id}')">Annuler</button></div>`).join('')||'<div class="panel empty">Aucun coaching à venir. Choisissez votre coach pour commencer.</div>'}<div class="gymsectionheading"><div><h2>Trouvez votre partenaire de progression</h2><p>Équipe et disponibilités de démonstration.</p></div></div><div class="coachgrid">${coaches.map((c,i)=>`<article class="panel coachcard"><div class="coachportrait"><span>${c.initials}</span><small>ORION COACH / 0${i+1}</small></div><div class="coachbody"><span class="eyebrow">${c.specialty}</span><h2>${c.name}</h2><p>${c.note}</p><div class="inline"><span class="badge vip">30 min</span><span class="muted">Au club · individuel</span></div><button class="btn primary wide" onclick="coachingForm('${c.id}')">Choisir un créneau ${icon('arrow')}</button></div></article>`).join('')}</div><p class="subtle" style="margin-top:20px">Créneaux à l’heure du club · Conakry (UTC).</p>`;}
function coachingForm(id){if(!memberReady())return;const m=currentMember(),c=coaches.find(c=>c.id===id);if(!c)return;if(!active(m)||!coachQuota(m))return modal('Coaching individuel',`<p class="muted">Un abonnement Premium ou VIP actif permet de réserver les séances incluses.</p><button class="btn primary" style="margin-top:20px" onclick="$('#modal').close();go('membership')">Voir mon abonnement</button>`);modal('Réserver avec '+c.name,`<form onsubmit="event.preventDefault();bookCoaching('${id}')"><div class="notice">${coachQuota(m)} séance(s) incluse(s) par semaine · durée 30 minutes.</div><div class="field"><label for="coachDay">Jour</label><select id="coachDay">${Array.from({length:14},(_,i)=>shift(i+1)).map(d=>`<option value="${d}">${shortDay(d)}</option>`).join('')}</select></div><div class="field"><label for="coachTime">Heure de début</label><select id="coachTime">${['08:00','10:00','14:00','17:00','19:00'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="coachFocus">Ce que je souhaite travailler</label><select id="coachFocus"><option>Faire un premier bilan</option><option>Découvrir les machines</option><option>Revoir ma technique</option><option>Adapter ma routine</option></select></div><p id="coachError" class="formerror" role="alert"></p><button class="btn primary wide">Confirmer mon rendez-vous</button></form>`);}
function bookCoaching(coachId){if(!memberReady())return;const m=currentMember(),b={id:uid(),memberId:m.id,coachId,day:$('#coachDay').value,time:$('#coachTime').value,focus:$('#coachFocus').value};const fail=t=>{$('#coachError').textContent=t;toast(t)};if(!active(m)||!coachQuota(m))return fail('Un abonnement Premium ou VIP actif est nécessaire.');if(!coaches.some(c=>c.id===coachId)||!Array.from({length:14},(_,i)=>shift(i+1)).includes(b.day)||!['08:00','10:00','14:00','17:00','19:00'].includes(b.time)||!['Faire un premier bilan','Découvrir les machines','Revoir ma technique','Adapter ma routine'].includes(b.focus))return fail('Sélectionnez un créneau et un objectif valides.');if(b.day>m.expiry)return fail('Ce rendez-vous est après la fin de votre abonnement.');if(myCoaching().filter(x=>weekOf(x.day)===weekOf(b.day)).length>=coachQuota(m))return fail('Tous vos crédits sont déjà utilisés pour cette semaine.');const start=coachTime(b),end=start+30*60000;if(state.coachBookings.some(x=>(x.memberId===m.id||x.coachId===coachId)&&coachTime(x)<end&&coachTime(x)+30*60000>start))return fail('Ce créneau est déjà réservé. Choisissez une autre heure.');if(myBookings().some(x=>{const s=state.classSlots.find(s=>s.id===x.slotId);return s&&slotTime(s)<end&&slotTime(s)+s.minutes*60000>start}))return fail('Vous avez déjà un cours à cette heure.');state.coachBookings.push(b);save();$('#modal').close();go('coaching');toast('Votre rendez-vous est réservé dans la démo.');}
function cancelCoaching(id){if(!memberReady())return;const b=state.coachBookings.find(b=>b.id===id&&b.memberId===currentMember().id);if(!b||coachTime(b)<=Date.now())return;state.coachBookings=state.coachBookings.filter(b=>b.id!==id);save();render();toast('Rendez-vous annulé. Votre crédit est à nouveau disponible.');}
function coachingStaffPanel(){if(!can('clients'))return'';const bookings=state.coachBookings.filter(b=>coachTime(b)>Date.now()).sort((a,b)=>coachTime(a)-coachTime(b));return`<section class="panel" style="margin-bottom:22px"><div class="panelhead"><h2>Coaching · rendez-vous à venir</h2><span class="badge vip">${bookings.length}</span></div><div class="tablewrap"><table><thead><tr><th>Membre</th><th>Coach</th><th>Créneau</th><th>Objectif</th></tr></thead><tbody>${bookings.map(b=>`<tr><td>${esc(state.members.find(m=>m.id===b.memberId)?.name||'Membre')}</td><td>${esc(coaches.find(c=>c.id===b.coachId)?.name||'Coach')}</td><td>${shortDay(b.day)} · ${b.time}</td><td>${esc(b.focus)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Les réservations de coaching apparaîtront ici.</td></tr>'}</tbody></table></div></section>`;}
function fitnessPage(){const m=currentMember(),next=myCoaching().find(b=>coachTime(b)>Date.now());return fitnessPageBase().replace('<div class="gymherogrid">',`<div class="memberquick"><button onclick="go('program')">${icon('chart')}<span>Mon programme<small>Une semaine à mon rythme</small></span>${icon('arrow')}</button><button onclick="go('coaching')">${icon('users')}<span>Mon coaching<small>${next?shortDay(next.day)+' · '+next.time:'Choisir mon prochain rendez-vous'}</small></span>${icon('arrow')}</button><button onclick="go('shop')">${icon('bag')}<span>Mes avantages<small>${active(m)?'−'+state.settings.memberDiscount+' % en boutique':'Découvrir la boutique'}</small></span>${icon('arrow')}</button></div><div class="gymherogrid">`);}
function progressPage(){const f=fitness(),days=Array.from({length:28},(_,i)=>shift(i-27)),logged=new Set(f.logs.map(l=>l.day)),real=f.logs.filter(l=>!l.example),badges=[['Premier pas',real.length>=1,'Terminer 1 séance'],['Le rythme est là',real.length>=5,'Terminer 5 séances'],['Club des 10',real.length>=10,'Terminer 10 séances']];return progressPageBase()+`<div class="gymsectionheading"><div><h2>28 jours pour voir votre régularité</h2><p>Un point doré par jour avec une séance enregistrée, exemples compris.</p></div></div><section class="panel calendarpanel"><div class="activitycalendar">${days.map(d=>`<div class="activityday ${logged.has(d)?'done':''}"><span>${new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}</span><i aria-label="${logged.has(d)?'Séance enregistrée':'Pas de séance'}"></i></div>`).join('')}</div></section><div class="gymsectionheading"><div><h2>Mes étapes franchies</h2><p>Vos séances terminées dans la démo débloquent ces repères. Les exemples ne comptent pas.</p></div></div><div class="milestones">${badges.map(([name,earned,detail])=>`<article class="panel ${earned?'earned':''}"><span class="milestoneicon">${earned?'✦':'◇'}</span><div><h3>${name}</h3><p>${detail}</p><small>${earned?'Étape franchie':'À vous de jouer'}</small></div></article>`).join('')}</div>`;}



function clients(){return can('clients')?coachingStaffPanel()+requestsPanel()+clientsBase():deny()}
